starterSets.forEach(set=>{set.cards.push(...(starterExtensions[set.id]||[]).map(([q,a])=>({q,a}))) });
let state = loadState();
let currentView = "home";
let study = null;
let toastTimer;

function loadState(){
  try { const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)); if(saved&&Array.isArray(saved.sets)){const starterIds=new Set(starterSets.map(s=>s.id));return {...saved,sets:[...starterSets.map(s=>({...s,cards:s.cards.map(c=>({...c}))})),...saved.sets.filter(s=>!starterIds.has(s.id))],stats:saved.stats||{sessions:0,answered:0},recent:saved.recent||[],studyHistory:saved.studyHistory||[],studyGoal:saved.studyGoal||3,reviewQueue:saved.reviewQueue||[]};} } catch(e){}
  return {sets:starterSets.map(s=>({...s,cards:s.cards.map(c=>({...c}))})),stats:{sessions:0,answered:0},recent:[],studyHistory:[],studyGoal:3,reviewQueue:[]};
}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
function iconColor(set){return set.color||"blue"}
function setIcon(set){return `<span class="subject-icon ${iconColor(set)}">${esc(set.icon||"✦")}</span>`}
function navigate(view){currentView=view;study=null;render();}
function render(){
  document.getElementById("crumb-current").textContent=study?(study.mode==="results"?"Session complete":study.mode==="quiz"?"Practice quiz":"Flashcards"):currentView==="library"?"My study sets":currentView==="create"?"Create a study set":"Home";
  document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===currentView&&!study));
  renderSidebar();
  const content=document.getElementById("content");
  if(study){content.innerHTML=study.mode==="results"?renderResults():study.mode==="flash"?renderFlash():study.mode==="guide"?renderGuide():renderQuiz();bindStudy();return;}
  content.innerHTML=currentView==="library"?renderLibrary():currentView==="create"?renderBuilder():renderHome();
  bindPage();
}
function renderSidebar(){
  document.getElementById("side-sets").innerHTML=state.sets.slice(0,5).map(s=>`<button class="side-set" data-set="${esc(s.id)}">${esc(s.title)}</button>`).join("");
  document.querySelectorAll(".side-set").forEach(b=>b.onclick=()=>openSet(b.dataset.set));
}
function renderHome(){
  const recent=state.recent.slice(0,3).map(r=>{const s=state.sets.find(x=>x.id===r.id);return s?`<div class="recent-row">${setIcon(s)}<div class="recent-info"><strong>${esc(s.title)}</strong><span>${esc(r.mode)} · ${esc(r.when)}</span></div><button class="text-btn" data-open="${esc(s.id)}">Study →</button></div>`:""}).join("");
  return `<section class="welcome-row"><div><div class="eyebrow">YOUR STUDY SPACE</div><h1>Good morning, Oliver <span>☀</span></h1><p>A little progress today goes a long way. What would you like to learn?</p></div><button class="primary-btn" id="create-set"><span class="plus">＋</span>Create a study set</button></section>
  <section class="home-actions"><button class="secondary-btn" id="upload-notes">↑ &nbsp;Upload notes</button><button class="secondary-btn" id="explore-topics">⌕ &nbsp;Explore topics</button></section>
  <section class="dashboard-grid"><div class="hero-card"><div class="hero-copy"><div class="eyebrow">YOUR NEXT STUDY SESSION</div><h2>Turn a few minutes into real progress.</h2><p>Pick up where you left off or choose a set to start fresh.</p><button class="primary-btn hero-btn" id="browse-sets">Browse study sets&nbsp; →</button></div><div class="hero-art"><div class="art-card back"><div class="art-line"></div><div class="art-line"></div><div class="art-line"></div></div><div class="art-card front"><span class="art-spark">✦</span><div class="art-line"></div><div class="art-line"></div></div></div></div>
  <div class="stat-card"><div class="stat-top"><span>Your learning journey</span><span class="stat-icon">↗</span></div><div><div class="stat-number">${state.stats.sessions}</div><div class="stat-foot">study sessions completed</div></div><div class="stat-foot"><span>${state.stats.answered}</span> questions answered so far</div></div></section>
  <section><div class="section-head"><h2>Pick up a study set</h2><button class="text-btn" id="view-all">View all&nbsp; →</button></div><div class="sets-grid">${state.sets.slice(0,3).map(setCard).join("")||emptySets()}</div></section>
  <section><div class="section-head"><h2>Recently studied</h2><small>Your activity stays on this device</small></div><div class="recent-list">${recent||`<div class="quiz-empty">Your recent sessions will appear here after you study.</div>`}</div></section>`;
}
function setCard(s){return `<article class="set-card" data-open="${esc(s.id)}"><div class="set-card-top">${setIcon(s)}<span class="more">···</span></div><h3>${esc(s.title)}</h3><p>${esc(s.subject||"Study set")}</p><div class="set-card-bottom"><span class="card-count">▤ &nbsp;${s.cards.length} cards</span><span class="mini-link">Study set&nbsp; →</span></div></article>`}
function emptySets(){return `<div class="empty-card"><strong>Your study space starts here</strong>Create a set from your class notes, then practice at your own pace.<br><br><button class="primary-btn" id="create-empty">＋ Create your first set</button></div>`}
function renderLibrary(){return `<section class="page-heading"><div class="eyebrow">YOUR COLLECTION</div><h1>My study sets</h1><p>All your study material, ready when you are.</p><div class="library-tools"><input class="search-input" id="search" placeholder="⌕  Search study sets" aria-label="Search study sets"><button class="primary-btn" id="create-set">＋ New study set</button></div></section><div class="sets-grid" id="library-grid">${state.sets.map(setCard).join("")||emptySets()}</div>`}
function bindPage(){
  document.getElementById("create-set")?.addEventListener("click",showCreateModal);
  document.getElementById("side-add").onclick=showCreateModal;
  document.getElementById("browse-sets")?.addEventListener("click",()=>navigate("library"));
  document.getElementById("view-all")?.addEventListener("click",()=>navigate("library"));
  document.getElementById("create-empty")?.addEventListener("click",showCreateModal);
  document.getElementById("explore-topics")?.addEventListener("click",()=>navigate("library"));
  document.getElementById("upload-notes")?.addEventListener("click",uploadNotes);
  document.querySelectorAll(".builder-home").forEach(button=>button.addEventListener("click",()=>navigate("home")));
  document.querySelectorAll("[data-builder-tab]").forEach(button=>button.addEventListener("click",()=>switchBuilderTab(button.dataset.builderTab)));
  document.getElementById("add-card")?.addEventListener("click",()=>{addBuilderCard();document.querySelector(".builder-card-row:last-child input")?.focus();});
  document.getElementById("generate-guide")?.addEventListener("click",generateGuide);
  document.getElementById("builder-form")?.addEventListener("submit",saveBuilderSet);
  document.querySelectorAll(".remove-card").forEach(button=>button.addEventListener("click",()=>{button.closest(".builder-card-row").remove();updateBuilderCount()}));
  document.querySelectorAll("[data-open]").forEach(el=>el.addEventListener("click",()=>openSet(el.dataset.open)));
  document.getElementById("search")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();document.getElementById("library-grid").innerHTML=state.sets.filter(s=>(s.title+" "+s.subject).toLowerCase().includes(q)).map(setCard).join("")||`<div class="empty-card">No study sets match “${esc(q)}”.</div>`;document.querySelectorAll("#library-grid [data-open]").forEach(el=>el.onclick=()=>openSet(el.dataset.open));});
}
function uploadNotes(){
  const picker=document.createElement("input");picker.type="file";picker.accept=".txt,.md,text/plain,text/markdown";picker.setAttribute("aria-label","Choose a text file of study cards");
  picker.onchange=()=>{const file=picker.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{navigate("create");document.getElementById("builder-title").value=file.name.replace(/\.(txt|md)$/i,"");const rows=String(reader.result||"").split("\n").map(line=>line.split("|" )).filter(pair=>pair.length>=2&&pair[0].trim()&&pair.slice(1).join("|").trim()).map(pair=>({q:pair[0].trim(),a:pair.slice(1).join("|").trim()}));if(rows.length){document.getElementById("builder-cards").innerHTML="";rows.forEach(card=>addBuilderCard(card));showToast(`${rows.length} cards imported. Review them before saving.`);}else showToast("No prompt | answer rows found. Add cards in the builder.");};reader.onerror=()=>showToast("That file could not be read. Try a plain text or Markdown file.");reader.readAsText(file);};picker.click();
}
function showCreateModal(){
  navigate("create");
}
function renderBuilder(){return `<div class="builder-page"><button class="back-link builder-back builder-home" type="button">← &nbsp;Back to home</button><div class="builder-heading"><div><div class="eyebrow">STUDY SET BUILDER</div><h1>Build your next study session</h1><p>Create flashcards, turn them into a practice quiz, and add a study guide.</p></div><button class="secondary-btn" id="upload-notes" type="button">↑ &nbsp;Import notes</button></div><form id="builder-form"><div class="builder-meta"><div class="field"><label for="builder-title">Study set name</label><input id="builder-title" required maxlength="60" placeholder="e.g. Organic Chemistry: Reactions"></div><div class="field"><label for="builder-subject">Subject</label><input id="builder-subject" maxlength="30" placeholder="e.g. Chemistry"></div></div><div class="builder-workspace"><aside class="builder-tools"><div class="tool-label">CREATE WITH THIS SET</div><button class="builder-tab active" type="button" data-builder-tab="flashcards"><span>▤</span><span><strong>Flashcards</strong><small>Build your study cards</small></span></button><button class="builder-tab" type="button" data-builder-tab="quiz"><span>☑</span><span><strong>Practice quiz</strong><small>Set up a knowledge check</small></span></button><button class="builder-tab" type="button" data-builder-tab="guide"><span>✎</span><span><strong>Study guide</strong><small>Summarize key ideas</small></span></button><div class="tool-note">One set powers every study mode. Add your material once, then review it in different ways.</div></aside><div class="builder-panel"><section class="builder-section" data-builder-panel="flashcards"><div class="panel-heading"><div><h2>Flashcards</h2><p>Add a prompt and answer for every concept you want to remember.</p></div><span class="panel-count" id="builder-count">2 cards</span></div><div class="card-editor-head"><span>FRONT · PROMPT</span><span>BACK · ANSWER</span></div><div id="builder-cards">${builderCardRow()}${builderCardRow()}</div><button class="add-card-btn" type="button" id="add-card">＋ Add another card</button></section><section class="builder-section hidden" data-builder-panel="quiz"><div class="panel-heading"><div><h2>Practice quiz</h2><p>QuizMe turns each prompt into a four-choice question using the answers in this set.</p></div><span class="panel-badge">AUTO-GENERATED</span></div><div class="quiz-setup-card"><div class="setup-icon">☑</div><div><strong>Multiple-choice practice</strong><p>Each flashcard becomes a question. The correct answer comes from the back of the card, with three distractors drawn from this set and your study library.</p></div></div><div class="quiz-fixed-count"><strong>10 questions per quiz</strong><span>Add at least 10 cards to a set to enable quiz mode.</span></div><label class="check-row"><input type="checkbox" id="quiz-shuffle" checked><span><strong>Shuffle question order</strong><small>Mix up the sequence each time you practice.</small></span></label></section><section class="builder-section hidden" data-builder-panel="guide"><div class="panel-heading"><div><h2>Study guide</h2><p>Make a concise review sheet from your cards, then add your own notes.</p></div></div><div class="guide-callout">✦ &nbsp;Generate a starting guide from your flashcards. You can edit the result before saving.</div><div class="field"><label for="guide-content">Your study guide</label><textarea id="guide-content" class="guide-textarea" placeholder="Your generated guide will appear here. Add definitions, examples, formulas, or connections you want to remember."></textarea></div><button type="button" class="secondary-btn" id="generate-guide">✦ &nbsp;Generate from flashcards</button></section><div class="builder-footer"><button type="button" class="text-btn builder-home">Cancel</button><button type="submit" class="primary-btn">Save study set&nbsp; →</button></div></div></div></form></div>`}
function builderCardRow(card={q:"",a:""}){return `<div class="builder-card-row"><label><span class="sr-only">Card prompt</span><textarea class="card-prompt" placeholder="Write a question or key term">${esc(card.q||"")}</textarea></label><label><span class="sr-only">Card answer</span><textarea class="card-answer" placeholder="Write the answer or explanation">${esc(card.a||"")}</textarea></label><button type="button" class="remove-card" aria-label="Remove card">×</button></div>`}
function addBuilderCard(card={q:"",a:""}){document.getElementById("builder-cards").insertAdjacentHTML("beforeend",builderCardRow(card));document.querySelectorAll(".remove-card").forEach(button=>button.onclick=()=>{button.closest(".builder-card-row").remove();updateBuilderCount()});updateBuilderCount()}
function switchBuilderTab(tab){document.querySelectorAll("[data-builder-tab]").forEach(button=>button.classList.toggle("active",button.dataset.builderTab===tab));document.querySelectorAll("[data-builder-panel]").forEach(panel=>panel.classList.toggle("hidden",panel.dataset.builderPanel!==tab));}
function updateBuilderCount(){const n=document.querySelectorAll(".builder-card-row").length;const label=document.getElementById("builder-count");if(label)label.textContent=`${n} ${n===1?"card":"cards"}`}
function generateGuide(){const cards=[...document.querySelectorAll(".builder-card-row")].map(row=>({q:row.querySelector(".card-prompt").value.trim(),a:row.querySelector(".card-answer").value.trim()})).filter(card=>card.q&&card.a);if(!cards.length){showToast("Add a few flashcards first, then generate your guide.");return}document.getElementById("guide-content").value=cards.map((card,index)=>`${index+1}. ${card.q}\n${card.a}`).join("\n\n");showToast("Study guide drafted from your cards. Edit it to make it yours.")}
function saveBuilderSet(event){event.preventDefault();const title=document.getElementById("builder-title").value.trim(),subject=document.getElementById("builder-subject").value.trim()||"My study set";const cards=[...document.querySelectorAll(".builder-card-row")].map(row=>({q:row.querySelector(".card-prompt").value.trim(),a:row.querySelector(".card-answer").value.trim()})).filter(card=>card.q&&card.a);if(cards.length<2){showToast("Add at least two complete flashcards before saving.");switchBuilderTab("flashcards");return}const colors=["violet","mint","amber","blue"];state.sets.unshift({id:"set-"+Date.now(),title,subject,icon:"✦",color:colors[Math.floor(Math.random()*colors.length)],cards,guide:document.getElementById("guide-content").value.trim(),quizSettings:{shuffle:document.getElementById("quiz-shuffle").checked}});saveState();currentView="library";render();showToast("Study set saved. Choose a mode to start learning.")}
function openSet(id){const set=state.sets.find(s=>s.id===id);if(!set)return;study={setId:id,mode:"choose"};renderModeChoice();}
function renderModeChoice(){const s=state.sets.find(x=>x.id===study.setId);const root=document.getElementById("modal-root");root.innerHTML=`<div class="overlay" id="overlay"><div class="modal"><div class="modal-head"><div><h2>Ready to study?</h2><p>${esc(s.title)} · ${s.cards.length} cards</p></div><button class="close-btn" id="close-modal">×</button></div><p style="color:#68738a;font-size:12px;margin:0 0 16px">Choose a study mode to get started.</p><div style="display:grid;gap:10px"><button class="answer-option" id="start-flash">${setIcon(s)} <span><strong>Flashcards</strong><br><small>Review each card at your own pace</small></span></button><button class="answer-option" id="start-quiz">${setIcon(s)} <span><strong>Practice quiz</strong><br><small>Test what you remember with multiple choice</small></span></button>${s.guide?`<button class="answer-option" id="start-guide">${setIcon(s)} <span><strong>Study guide</strong><br><small>Read your saved review notes</small></span></button>`:""}</div></div></div>`;const close=()=>{root.innerHTML="";study=null};document.getElementById("close-modal").onclick=close;document.getElementById("overlay").onclick=e=>{if(e.target.id==="overlay")close()};document.getElementById("start-flash").onclick=()=>beginStudy("flash");document.getElementById("start-quiz").onclick=()=>beginStudy("quiz");document.getElementById("start-guide")?.addEventListener("click",()=>beginStudy("guide"));}
function beginStudy(mode){const setId=study.setId,set=state.sets.find(item=>item.id===setId);let quizCards=[];if(mode==="quiz"){if(set.cards.length<10){showToast("Add at least 10 flashcards before starting a 10-question quiz.");return}let entries=[...set.cards];if(set.quizSettings?.shuffle!==false)entries.sort(()=>Math.random()-.5);quizCards=entries.slice(0,10);const quizSet={cards:quizCards};if(quizCards.some(card=>quizDistractors(quizSet,card).length<3)){showToast("Add more cards with distinct answers so every question has four choices.");return}}document.getElementById("modal-root").innerHTML="";study={setId,mode,index:0,flipped:false,selected:null,answers:[]};if(mode==="quiz")study.quizCards=quizCards;render();}
function currentSet(){return state.sets.find(s=>s.id===study.setId)}
function renderStudyHeader(s){return `<div class="study-toolbar"><button class="back-link" id="leave-study">← &nbsp;Back to sets</button><span style="color:#9aa2b1;font-size:11px">${esc(s.subject||"Study set")}</span></div><div class="study-title"><h1>${esc(s.title)}</h1><p>${study.mode==="flash"?"Take your time. Flip each card when you're ready.":"Choose the best answer for each question."}</p></div>`}
function renderFlash(){const s=currentSet(),card=s.cards[study.index],n=study.index+1;return `<div class="study-main">${renderStudyHeader(s)}<div class="progress-row"><span>Card ${n} of ${s.cards.length}</span><span>${Math.round(n/s.cards.length*100)}% complete</span></div><div class="progress-track"><div class="progress-fill" style="width:${n/s.cards.length*100}%"></div></div><div class="flashcard" id="flip-card" role="button" tabindex="0"><span class="flashcard-label">${study.flipped?"ANSWER":"QUESTION"}</span><div class="flashcard-text">${esc(study.flipped?card.a:card.q)}</div><span class="flip-hint">↻ &nbsp;Click to flip</span></div><div class="flash-actions"><button class="secondary-btn" id="prev-card" ${study.index===0?"disabled":""}>← &nbsp;Previous</button><button class="secondary-btn" id="flip-button">↻ &nbsp;Flip card</button><button class="primary-btn" id="next-card">${n===s.cards.length?"Finish":"Next card"}&nbsp; →</button></div></div>`}
function quizDistractors(set,card){return [...new Set([...(card.d||[]),...set.cards.filter(other=>other!==card).map(other=>other.a)].filter(answer=>answer&&answer!==card.a))]}
function quizQuestion(s,index){const card=s.cards[index];const others=quizDistractors(s,card).sort(()=>Math.random()-.5).slice(0,3);const choices=[card.a,...others].sort(()=>Math.random()-.5);return {prompt:card.q,correct:card.a,choices}}
function ensureQuestion(){if(!study.questions)study.questions=(study.quizCards||currentSet().cards).map((_,i)=>quizQuestion({cards:study.quizCards||currentSet().cards},i));}
function renderQuiz(){const s=currentSet();ensureQuestion();const total=study.questions.length,q=study.questions[study.index],selected=study.selected;const answered=selected!==null;return `<div class="study-main">${renderStudyHeader(s)}<div class="progress-row"><span>Question ${study.index+1} of ${total}</span><span>${Math.round((study.index+1)/total*100)}% complete</span></div><div class="progress-track"><div class="progress-fill" style="width:${(study.index+1)/total*100}%"></div></div><div class="quiz-card"><div class="question-kicker">CHOOSE YOUR ANSWER</div><div class="question-text">${esc(q.prompt)}</div><div class="answers">${q.choices.map((choice,i)=>{let cls="";if(answered&&choice===q.correct)cls="correct";else if(answered&&i===selected&&choice!==q.correct)cls="wrong";else if(answered&&i===selected)cls="selected";return `<button class="answer-option ${cls}" data-answer="${i}" ${answered?"disabled":""}><span class="answer-letter">${"ABCD"[i]}</span>${esc(choice)}</button>`}).join("")}</div>${answered?`<div class="feedback ${q.choices[selected]===q.correct?"good":"bad"}"><strong>${q.choices[selected]===q.correct?"That's right!":"Not quite."}</strong> ${q.choices[selected]===q.correct?"Nice work remembering that.":`The answer is: ${esc(q.correct)}`}</div>`:""}<div class="quiz-actions"><button class="secondary-btn" id="skip-question" ${answered?"disabled":""}>Skip question</button><button class="primary-btn" id="next-question" ${!answered?"disabled":""}>${study.index===total-1?"See results":"Next question"}&nbsp; →</button></div></div></div>`}
function renderGuide(){const s=currentSet();return `<div class="study-main"><div class="study-toolbar"><button class="back-link" id="back-to-modes">← &nbsp;Back to study modes</button>${setIcon(s)}</div><div class="study-title"><div class="eyebrow">STUDY GUIDE</div><h1>${esc(s.title)}</h1><p>Your saved notes for this study set.</p></div><article class="saved-guide">${esc(s.guide||"No guide has been added yet.")}</article></div>`}
function bindStudy(){document.getElementById("leave-study")?.addEventListener("click",()=>{study=null;render()});document.getElementById("back-to-modes")?.addEventListener("click",()=>{study.mode="choose";renderModeChoice()});if(study.mode==="flash"){const flip=()=>{study.flipped=!study.flipped;render()};document.getElementById("flip-card").onclick=flip;document.getElementById("flip-card").onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();flip()}};document.getElementById("flip-button").onclick=flip;document.getElementById("prev-card").onclick=()=>{if(study.index>0){study.index--;study.flipped=false;render()}};document.getElementById("next-card").onclick=()=>{if(study.index<currentSet().cards.length-1){study.index++;study.flipped=false;render()}else finishFlash()};}else if(study.mode==="quiz"){document.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{study.selected=Number(b.dataset.answer);render()});document.getElementById("skip-question").onclick=()=>{const q=study.questions[study.index];study.answers.push({skip:true,prompt:q.prompt,correctAnswer:q.correct});if(study.index===study.questions.length-1){finishQuiz();return}moveQuestion()};document.getElementById("next-question").onclick=()=>{const q=study.questions[study.index],correct=q.choices[study.selected]===q.correct;study.answers.push({correct,prompt:q.prompt,answer:q.choices[study.selected],correctAnswer:q.correct});state.stats.answered++;if(study.index===study.questions.length-1){finishQuiz();return}moveQuestion()};}}
function moveQuestion(){if(study.index<study.questions.length-1){study.index++;study.selected=null;render()}}
function recordStudySession(mode){const now=new Date();state.stats.sessions++;state.studyHistory.unshift({date:now.toISOString(),setId:study.setId,mode});state.studyHistory=state.studyHistory.slice(0,180)}
function finishFlash(){recordStudySession("Flashcards");addRecent("Flashcards");saveState();study={...study,mode:"results",score:null};render()}
function finishQuiz(){recordStudySession("Practice quiz");const correctPrompts=new Set(study.answers.filter(answer=>answer.correct).map(answer=>answer.prompt));state.reviewQueue=state.reviewQueue.filter(item=>item.setId!==study.setId||!correctPrompts.has(item.prompt));const missed=study.answers.filter(answer=>!answer.correct).map(answer=>({setId:study.setId,prompt:answer.prompt,answer:answer.correctAnswer,date:new Date().toISOString()}));state.reviewQueue=[...missed,...state.reviewQueue].slice(0,40);addRecent("Practice quiz");saveState();study={...study,mode:"results",score:study.answers.filter(a=>a.correct).length};render()}
function addRecent(mode){state.recent.unshift({id:study.setId,mode,when:"Just now"});state.recent=state.recent.slice(0,8)}
function renderResults(){const s=currentSet(),score=study.score,total=score===null?s.cards.length:(study.questions?.length||s.cards.length),percentage=score===null?null:Math.round(score/total*100);let review=score===null?`<div class="review-item">You worked through all <strong>${total} cards</strong>. Keep the ones that felt tricky in mind for next time.</div>`:study.answers.map(a=>a.skip?`<div class="review-item"><strong>Skipped:</strong> ${esc(a.prompt)}<br>Answer: ${esc(a.correctAnswer)}</div>`:!a.correct?`<div class="review-item"><strong>Review:</strong> ${esc(a.prompt)}<br>Your answer: ${esc(a.answer)} · Answer: ${esc(a.correctAnswer)}</div>`:"").join("")||`<div class="review-item">You got every question right. Excellent recall!</div>`;return `<div class="study-main"><div class="study-toolbar"><button class="back-link" id="leave-study">← &nbsp;Back to sets</button><span style="color:#9aa2b1;font-size:11px">${esc(s.title)}</span></div><div class="results-card">${percentage===null?`<div class="result-ring" style="--score-angle:78deg"><div class="result-ring-inner">✓</div></div><h2>Session complete</h2><p>You made time to learn today. That counts.</p>`:`<div class="result-ring" style="--score-angle:${percentage*3.6}deg"><div class="result-ring-inner">${percentage}%</div></div><h2>${percentage>=80?"Great work!":percentage>=50?"Nice progress!":"Keep practicing!"}</h2><p>You got ${score} out of ${total} questions right.</p>`}<div class="review-box"><h3>${percentage===null?"A quick reflection":"What to review next"}</h3>${review}</div><div class="result-actions"><button class="secondary-btn" id="again-flash">Study flashcards</button>${percentage!==null?`<button class="primary-btn" id="retry-quiz">Try quiz again&nbsp; →</button>`:`<button class="primary-btn" id="again-quiz">Take a practice quiz&nbsp; →</button>`}</div></div></div>`}
document.addEventListener("click",e=>{if(e.target.closest(".nav-item")){navigate(e.target.closest(".nav-item").dataset.view);}});
document.addEventListener("click",e=>{if(e.target.id==="again-flash")beginStudy("flash");if(e.target.id==="retry-quiz"||e.target.id==="again-quiz")beginStudy("quiz");});
function weekStart(date=new Date()){const start=new Date(date.getFullYear(),date.getMonth(),date.getDate());start.setDate(start.getDate()-((start.getDay()+6)%7));start.setHours(0,0,0,0);return start}
function tutorWeekCount(){const start=weekStart();return state.studyHistory.filter(entry=>new Date(entry.date)>=start).length}
function openTutor(){const panel=document.getElementById("tutor-panel"),launch=document.getElementById("tutor-launch");panel.classList.remove("hidden");launch.setAttribute("aria-expanded","true");if(!document.getElementById("tutor-messages").children.length){const done=tutorWeekCount(),goal=state.studyGoal||3;addTutorMessage(`Hi, I’m Pip! I can help you find answers in your study sets and make a steady study plan. You’ve done ${done} of ${goal} sessions toward this week’s goal. What are you working on?`,"pip")};document.getElementById("tutor-input").focus()}
function closeTutor(){document.getElementById("tutor-panel").classList.add("hidden");document.getElementById("tutor-launch").setAttribute("aria-expanded","false")}
function addTutorMessage(message,role="pip",actions=[]){const list=document.getElementById("tutor-messages"),bubble=document.createElement("div");bubble.className=`tutor-message ${role}`;bubble.innerHTML=`<div class="tutor-bubble">${esc(message).replace(/\n/g,"<br>")}</div>${actions.length?`<div class="tutor-message-actions">${actions.map(action=>`<button type="button" data-pip-action="${esc(action.id)}">${esc(action.label)}</button>`).join("")}</div>`:""}`;list.appendChild(bubble);list.scrollTop=list.scrollHeight}
function setTutorGoal(value){const goal=Math.max(1,Math.min(14,Number(value)||3));state.studyGoal=goal;saveState();addTutorMessage(`Done! Your weekly goal is ${goal} study sessions. I’ll keep your progress here and help you find a small next step.`)}
function tutorPlan(){const goal=state.studyGoal||3,done=tutorWeekCount(),remaining=Math.max(0,goal-done);const next=state.reviewQueue[0];return `Your goal is ${goal} sessions this week, and you’ve completed ${done}. ${remaining?`${remaining} more ${remaining===1?"session":"sessions"} to go. Try one 10-minute session today${next?` reviewing “${next.prompt}”`:" with a set you’re studying"}, then space the rest across the week.`:"You’ve reached your goal. Keep the rhythm going with a short review when it fits."}`}
function tutorReview(){const item=state.reviewQueue[0];if(item){const set=state.sets.find(s=>s.id===item.setId);return `A good place to focus is ${set?set.title:"a recent quiz"}: “${item.prompt}” The answer to review is: ${item.answer}. A quick flashcard pass, then retrying the quiz, should help.`}const recent=state.recent[0],set=recent&&state.sets.find(s=>s.id===recent.id);return set?`No missed quiz answers are queued yet. You could review ${set.title}, your most recent set, for five minutes and see which cards still feel uncertain.`:"After you take a practice quiz, I can point out missed questions to revisit. Pick any study set to get started."}
function tutorFindCard(message){const words=message.toLowerCase().match(/[a-z0-9]+/g)||[],stop=new Set(["what","when","where","which","who","why","how","does","do","did","is","are","was","were","the","a","an","of","in","on","to","for","with","about","explain","tell","me","please","can","you","define","describe","help","understand","this","that","it","my"]),terms=words.filter(word=>word.length>1&&!stop.has(word));let best=null,bestScore=0;for(const set of state.sets){for(const card of set.cards){const q=(set.title+" "+set.subject+" "+card.q).toLowerCase(),a=card.a.toLowerCase();let score=0;for(const term of terms){if(q.includes(term))score+=3;if(a.includes(term))score+=2}if(score>bestScore){bestScore=score;best={set,card}}}}return bestScore>=2?best:null}
function answerTutor(message){const text=message.trim(),lower=text.toLowerCase();if(!text)return;if(/(?:goal).{0,24}\b(\d{1,2})\b/i.test(text)){const amount=Number(text.match(/(?:goal).{0,24}\b(\d{1,2})\b/i)[1]);setTutorGoal(amount);return}if(/\b(hi|hello|hey)\b/.test(lower)){addTutorMessage("Hey! Tell me a class topic, ask about a card, or ask me to make a study plan.");return}if(/\b(goal|plan|schedule|keep up|behind|study this week|study plan)\b/.test(lower)){addTutorMessage(tutorPlan());return}if(/\b(review|weak|missed|wrong|struggle|hardest)\b/.test(lower)){addTutorMessage(tutorReview());return}if(/\b(quiz me|start a quiz|test me)\b/.test(lower)){const recent=state.recent[0],set=state.sets.find(s=>s.id===(recent&&recent.id))||state.sets[0];if(set){addTutorMessage(`Let’s practice ${set.title}. I’ll open its study modes for you.`);openSet(set.id)}else addTutorMessage("Create a study set first and I can help you practice it.");return}const match=tutorFindCard(text);if(match){addTutorMessage(`From ${match.set.title}: ${match.card.a}\n\nCard to check yourself: ${match.card.q}`);return}addTutorMessage("I can answer from the flashcards you’ve saved on this device, but I don’t have a live AI model connected. Try asking about a topic or term from one of your study sets, or ask me for a study plan.")}
function tutorAction(action){if(action==="plan")addTutorMessage(tutorPlan());else if(action==="review")addTutorMessage(tutorReview());else if(action==="goal")addTutorMessage("How many sessions would you like to aim for this week?", "pip",[{id:"goal:3",label:"3 sessions"},{id:"goal:5",label:"5 sessions"},{id:"goal:7",label:"7 sessions"}]);else if(action.startsWith("goal:"))setTutorGoal(action.split(":")[1]);else if(action==="quiz"){const set=state.sets.find(s=>s.id===(state.recent[0]&&state.recent[0].id))||state.sets[0];if(set)openSet(set.id)}}
document.getElementById("tutor-launch").addEventListener("click",openTutor);
document.getElementById("tutor-close").addEventListener("click",closeTutor);
document.getElementById("tutor-form").addEventListener("submit",event=>{event.preventDefault();const input=document.getElementById("tutor-input"),message=input.value.trim();if(!message)return;addTutorMessage(message,"user");input.value="";answerTutor(message)});
document.getElementById("tutor-panel").addEventListener("click",event=>{const action=event.target.closest("[data-pip-action]");if(action)tutorAction(action.dataset.pipAction)});
document.querySelectorAll(".tutor-quick-actions [data-pip-action]").forEach(button=>button.addEventListener("click",()=>tutorAction(button.dataset.pipAction)));
function showToast(message){const el=document.getElementById("toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2600)}
render();
